#!/usr/bin/env sh
#
# Print the git trailers of a message read on stdin, one per line, as
# git interpret-trailers --parse does. Shared by check-pr-trailers.sh and
# release-notes.sh, so the check and the notes always agree on what counts.
#
# Two things differ from running git interpret-trailers on its own:
#
# - CR characters are dropped. GitHub stores descriptions typed in the web
#   editor with CRLF line endings.
# - A closing footer after the last "---" line is set aside when it holds no
#   Changelog line. Tools that post pull requests (Claude Code among them)
#   append one, such as "---" and a "Generated by" line, below the trailers.
#   git's own divider handling cannot be used for this, because it cuts at the
#   FIRST "---" line, and a Markdown rule earlier in a description would hide
#   the trailers; --no-divider turns that off.

set -u

tr -d '\r' | awk '
	{ line[NR] = $0 }
	/^---[[:space:]]*$/ { last = NR }
	END {
		end = NR
		if (last) {
			keep = 0
			for (i = last + 1; i <= NR; i++)
				if (tolower(line[i]) ~ /^[[:space:]]*changelog[[:space:]]*:/) keep = 1
			if (!keep) end = last - 1
		}
		for (i = 1; i <= end; i++) print line[i]
	}' | git interpret-trailers --parse --no-divider
